package com.repairconnect.repository; import com.repairconnect.entity.*; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public interface ProviderRepository extends JpaRepository<ProviderProfile,Long>{Optional<ProviderProfile> findByUserEmail(String email); List<ProviderProfile> findByVerificationStatusAndCityContainingIgnoreCase(VerificationStatus status,String city); List<ProviderProfile> findByVerificationStatus(VerificationStatus status);}